SELECT "p"."Id", "p"."Name", "p"."PersonType" FROM "Peoples" AS "p" WHERE EXISTS ( SELECT 1 FROM "BaseItems" AS "b" WHERE "b"."Type" = @personType AND "b"."Name" = "p"."Name") AND NOT EXISTS ( SELECT 1 FROM "Peoples" AS "p0" WHERE EXISTS ( SELECT 1 FROM "BaseItems" AS "b0" WHERE "b0"."Type" = @personType AND "b0"."Name" = "p0"."Name") AND lower("p0"."Name") = lower("p"."Name") AND "p0"."Id" < "p"."Id") ORDER BY lower("p"."Name") LIMIT @p
